package fr.crewcmoi.teleport.gui;
import fr.crewcmoi.Main; import fr.crewcmoi.other.database.PlayerData; import fr.crewcmoi.other.utils.GuiItems; import fr.crewcmoi.other.utils.MoneyFormat; import fr.crewcmoi.pvp.database.BountyEntry; import fr.crewcmoi.pvp.database.TeamData; import fr.crewcmoi.teleport.database.HomeData; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.*; import java.util.*;
public class PlayerAdminGuiManager { private final Main plugin; public PlayerAdminGuiManager(Main p){plugin=p;} public void open(Player p){open(p,0);} public void open(Player p,int page){Bukkit.getScheduler().runTaskAsynchronously(plugin,()->{List<PlayerData> players=plugin.getDatabaseManager().getAllPlayers();Bukkit.getScheduler().runTask(plugin,()->{PlayerAdminHolder h=new PlayerAdminHolder();int max=Math.max(0,(players.size()-1)/45);h.setPage(Math.max(0,Math.min(page,max)));Inventory inv=Bukkit.createInventory(h,54,color("&8&lᴊᴏᴜᴇᴜʀꜱ • ᴀᴅᴍɪɴ &7• &f"+(h.getPage()+1)));h.setInventory(inv);render(h,players);p.openInventory(inv);});});}private void render(PlayerAdminHolder h,List<PlayerData> players){Inventory inv=h.getInventory();h.clear();for(int i=0;i<54;i++)inv.setItem(i,GuiItems.nothing(" "));int start=h.getPage()*45,end=Math.min(start+45,players.size());for(int i=start;i<end;i++){PlayerData d=players.get(i);int slot=i-start;inv.setItem(slot,playerItem(d));h.map(slot,d);}if(h.getPage()>0)inv.setItem(45,button(Material.ARROW,"&e« ᴘʀᴇᴄᴇᴅᴇɴᴛ"));if(end<players.size())inv.setItem(53,button(Material.ARROW,"&eꜱᴜɪᴠᴀɴᴛ »"));}private ItemStack playerItem(PlayerData d){ItemStack i=new ItemStack(Material.PLAYER_HEAD);SkullMeta m=(SkullMeta)i.getItemMeta();m.setOwningPlayer(Bukkit.getOfflinePlayer(d.getUuid()));m.setDisplayName(color("&e&l"+d.getName()));m.setLore(List.of(color("&7ꜱᴏʟᴅᴇ : &a"+MoneyFormat.format(d.getBalance())),"",color("&aᴄʟɪǫᴜᴇᴢ ᴘᴏᴜʀ ᴠᴏɪʀ ʟᴇꜱ ɪɴꜰᴏʀᴍᴀᴛɪᴏɴꜱ")));i.setItemMeta(m);return i;}public void openDetails(Player viewer,PlayerData d){Bukkit.getScheduler().runTaskAsynchronously(plugin,()->{List<HomeData> homes=plugin.getDatabaseManager().getHomes(d.getUuid());int claims=plugin.getDatabaseManager().getClaimsByOwner(d.getUuid()).size();TeamData team=plugin.getDatabaseManager().getTeamByPlayer(d.getUuid());double bounty=plugin.getDatabaseManager().getBounties(d.getUuid()).stream().mapToDouble(BountyEntry::getAmount).sum();Bukkit.getScheduler().runTask(plugin,()->{PlayerAdminDetailHolder h=new PlayerAdminDetailHolder();Inventory inv=Bukkit.createInventory(h,54,color("&8&lɪɴꜰᴏ • "+d.getName()));h.setInventory(inv);for(int i=0;i<54;i++)inv.setItem(i,GuiItems.nothing(" "));ItemStack head=new ItemStack(Material.PLAYER_HEAD);SkullMeta hm=(SkullMeta)head.getItemMeta();hm.setOwningPlayer(Bukkit.getOfflinePlayer(d.getUuid()));hm.setDisplayName(color("&e&l"+d.getName()));hm.setLore(List.of(color("&7UUID : &f"+d.getUuid()),color("&7ꜱᴛᴀᴛᴜᴛ : "+(Bukkit.getPlayer(d.getUuid())!=null?"&aEn ligne":"&7Hors ligne"))));head.setItemMeta(hm);inv.setItem(4,head);inv.setItem(20,info(Material.GOLD_INGOT,"&6&lꜱᴏʟᴅᴇ",List.of(color("&a"+MoneyFormat.format(d.getBalance())))));inv.setItem(22,info(Material.ENDER_PEARL,"&b&lʜᴏᴍᴇꜱ",List.of(color("&7Créés : &f"+homes.size()),color("&7Slots : &f"+plugin.getDatabaseManager().getHomeSlots(d.getUuid())))));inv.setItem(24,info(Material.IRON_BLOCK,"&a&lᴄʟᴀɪᴍꜱ",List.of(color("&7Claims : &f"+claims))));inv.setItem(29,info(Material.NAME_TAG,"&d&lᴇǫᴜɪᴘᴇ",List.of(color(team==null?"&7Aucune équipe":"&f"+team.getName()),color("&7Membres : &f"+(team==null?0:team.size())))));inv.setItem(31,info(Material.TARGET,"&c&lᴘʀɪᴍᴇ",List.of(color("&7Total : &c"+MoneyFormat.format(bounty)))));inv.setItem(49,button(Material.ARROW,"&c« ʀᴇᴛᴏᴜʀ"));viewer.openInventory(inv);});});}private ItemStack info(Material mat,String name,List<String> lore){ItemStack i=new ItemStack(mat);ItemMeta m=i.getItemMeta();m.setDisplayName(color(name));m.setLore(lore);i.setItemMeta(m);return i;}private ItemStack button(Material mat,String name){ItemStack i=new ItemStack(mat);ItemMeta m=i.getItemMeta();m.setDisplayName(color(name));i.setItemMeta(m);return i;}private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);}}
